<script setup lang="ts">
import {onBeforeRouteLeave} from 'vue-router';
import {useLiveDepartmentAccess} from '~/composables/useLiveDepartmentAccess';
import {liveRoles,liveCapabilities,roleOf,type ScopedSnapshot} from '~~/shared/access/live-policy';
import {ACCESS_ACTIONS,type AccessActionName} from '~~/shared/types/access-management';
import AccessMatrix from '../AccessMatrix.vue';
import DomainGroupImport from '../DomainGroupImport.vue';
const {scope,kind,metadata,subjects,selected,snapshots,search,hasMore,loading,reading,busy,error,notice,rights,role,denialMode,denied,plan,load,read,toggle,setRole,setRight,preview,apply,init}=useLiveDepartmentAccess();
const labels:Record<AccessActionName,string>={VIEW:'Просмотр',CREATE:'Создание',UPDATE:'Изменение',DELETE:'Удаление'};
function effectiveSummary(s:ScopedSnapshot,a:AccessActionName){const rows=s.data.filter(r=>r.isActive&&r.type==='TABLE');const count=rows.filter(r=>r.actions[a].effectiveGranted).length;return !rows.length?'Нет таблиц':count===rows.length?'Все таблицы':count?`${count} из ${rows.length}`:'Нет доступа';}
onBeforeRouteLeave(()=>busy.value?false:!plan.value||window.confirm('Уйти без применения подготовленного плана прав?'));
</script>
<template>
 <main class="role-preview live-access" aria-label="Права доступа" :aria-busy="busy||loading">
  <p v-if="error" class="rp-error" role="alert">{{ error }} <button v-if="!metadata" @click="init">Повторить</button></p><p v-if="notice" class="rp-notice" role="status">{{ notice }}</p>
  <fieldset :disabled="busy" class="live-controls">
   <section class="rp-card rp-scope"><label>Ресурсы подразделения<select v-model="scope"><option v-for="s in metadata?.scopes" :key="s.key" :value="s.key">{{ s.name }}</option><option v-if="metadata?.isSystemAdmin" value="other">Общие сервисы и системные права</option></select></label><label>Кому назначить<select v-model="kind"><option value="spaceGroup">Группам Space</option><option value="user">Сотрудникам</option><option value="department">Подразделениям</option><option value="domainGroup">Группам AD</option></select></label><div class="rp-actions"><button @click="load">Обновить список</button><button :disabled="!selected.length||reading" @click="read">Обновить права</button></div><p class="rp-draft-note">Данные загружены из БД. До нажатия «Применить изменения» назначения не меняются. Локальные тестовые черновики не используются.</p></section>
   <div class="live-layout">
    <aside class="rp-card live-subjects"><label>Поиск получателя<input v-model="search" type="search" maxlength="120" placeholder="Название, имя или логин"/></label><p class="rp-hint">{{ scope==='other'?'Выберите получателя':'Выберите до 10 получателей' }}</p><p v-if="loading">Загрузка…</p><label v-for="s in subjects" :key="s.id" :class="{'rp-selected':selected.includes(s.id)}"><input type="checkbox" :checked="selected.includes(s.id)" @change="toggle(s.id)"/><span><strong>{{ s.name }}</strong><small>{{ s.detail }}{{ !s.isActive?' · неактивен':'' }}</small></span></label><p v-if="!loading&&!subjects.length">Получатели не найдены.</p><p v-if="hasMore" class="rp-hint">Показаны первые 50. Уточните поиск.</p><DomainGroupImport v-if="kind==='domainGroup'&&metadata?.isSystemAdmin" @imported="load"/></aside>
    <div class="live-main">
     <AccessMatrix v-if="scope==='other'&&selected[0]" :key="`${kind}-${selected[0]}`" :kind="kind" :subject-id="selected[0]" :exclude-departments="true"/>
     <template v-else-if="scope!=='other'">
      <section class="rp-roles" aria-label="Шаблоны назначения"><button v-for="r in liveRoles" :key="r.key" :aria-pressed="role===r.key" @click="setRole(r.key)"><strong>{{ r.label }}</strong><small>{{ r.key==='admin'?'Данные, специальные операции и управление правами этого отдела':r.key==='moderator'?'Создание, изменение и удаление':r.key==='editor'?'Создание и изменение':'Открытие и просмотр' }}</small></button></section>
      <section class="rp-card"><h2>Шаблон нового назначения для всего подразделения</h2><div class="rp-capabilities"><label v-for="c in liveCapabilities" :key="c.key"><input type="checkbox" :checked="rights[c.key]" @change="setRight(c.key,($event.target as HTMLInputElement).checked)"/>{{ c.label }}</label></div><p class="rp-hint">Шаблон заменяет прямые разрешения на зарегистрированные таблицы этого отдела. Наследование и персональные запреты сохраняются. Общие сервисы и другие подразделения не затрагиваются.</p><p v-if="rights.restore&&scope==='lab'" class="rp-hint">У лабораторного контроля отдельного права восстановления нет: применяется существующая логика удаления/корзины.</p><p v-if="rights.manage" class="rp-notice">Получатель сможет назначать права пользователям и группам только в этом подразделении, включая передачу этой роли коллегам.</p>
       <details v-if="kind==='user'"><summary>Персональные запреты на весь отдел</summary><label><input v-model="denialMode" type="radio" value="keep"/> Сохранить имеющиеся запреты</label><label><input v-model="denialMode" type="radio" value="replace"/> Заменить запреты для выбранных сотрудников</label><div v-if="denialMode==='replace'" class="rp-capabilities"><label v-for="a in ACCESS_ACTIONS" :key="a"><input v-model="denied" type="checkbox" :value="a"/> Запретить: {{ labels[a] }}</label></div><p class="rp-hint">Запрет выше личных и групповых разрешений. Запрет просмотра закрывает все действия. Пустой список при замене снимает запреты этого отдела.</p></details>
       <div class="rp-bulk"><button class="rp-primary" :disabled="!selected.length||reading||snapshots.length!==selected.length" @click="preview">Предварительный анализ</button><span>Выбрано: {{ selected.length }}</span><small>Текущие смешанные наборы не превращаются в роли автоматически.</small></div>
      </section>
      <p v-if="reading" role="status">Проверяем назначения и наследование…</p>
      <section v-if="snapshots.length" class="rp-card"><h2>Сравнение действующего доступа</h2><div class="rp-table-scroll"><table><thead><tr><th>Получатель</th><th>Прямое назначение</th><th v-for="a in ACCESS_ACTIONS" :key="a">{{ labels[a] }}</th></tr></thead><tbody><tr v-for="s in snapshots" :key="s.subject.id"><td>{{ s.subject.name }}</td><td>{{ roleOf(s) }}</td><td v-for="a in ACCESS_ACTIONS" :key="a">{{ effectiveSummary(s,a) }}</td></tr></tbody></table></div><p class="rp-hint">Итог для активных таблиц с учётом наследования и запретов. Специальные операции и источники — ниже.</p></section>
      <section v-for="s in snapshots" :key="s.subject.id" class="rp-card"><header><div><h2>{{ s.subject.name }}</h2><p>{{ roleOf(s) }} · прямых прав: {{ s.summary.directPermissions }} · действующих: {{ s.summary.effectivePermissions }}</p></div></header><p v-if="s.directoryWarning" class="rp-error">{{ s.directoryWarning }}</p><p v-if="!s.subject.isActive" class="rp-notice">Получатель отключён. Назначения сохранены, но доступ не действует.</p><p v-if="s.subject.isSystemAdmin" class="rp-notice">Системные полномочия задаются конфигурацией. Шаблон отдела к этой учётной записи не применяется.</p>
       <details><summary>Фактические права и источники · {{ s.data.length }} ресурсов</summary><div class="rp-table-scroll"><table><thead><tr><th>Ресурс</th><th v-for="a in ACCESS_ACTIONS" :key="a">{{ labels[a] }}</th></tr></thead><tbody><tr v-for="r in s.data" :key="r.id"><td>{{ r.name }}<small>{{ r.isActive?'':'Ресурс отключён' }}</small></td><td v-for="a in ACCESS_ACTIONS" :key="a"><strong :class="r.actions[a].effectiveGranted?'rp-yes':'rp-no'">{{ r.actions[a].effectiveGranted?'Разрешено':'Нет доступа' }}</strong><small v-if="r.actions[a].directGranted">Прямое назначение</small><small v-if="r.actions[a].inheritedGranted">Отдел: {{ s.subject.department?.name }}</small><small v-for="g in r.actions[a].spaceGroups" :key="`s${g.id}`">Space: {{ g.name }}</small><small v-for="g in r.actions[a].domainGroups" :key="`d${g.id}`">AD: {{ g.name }}</small><small v-if="r.actions[a].blockedBy==='PERSONAL_DENY'">Персональный запрет</small></td></tr></tbody></table></div></details>
      </section>
      <section v-if="plan" class="rp-card live-plan"><h2>План изменений · {{ plan.count }} операций</h2><p>Проверьте выдачу и отзыв прав. Все выбранные получатели сохраняются одной транзакцией вместе с аудитом.</p><details v-for="p in plan.subjects" :key="p.id" open><summary>{{ p.name }} · {{ p.changes.length }} разрешений</summary><p v-for="w in p.warnings" :key="w" class="rp-notice">{{ w }}</p><div class="rp-table-scroll"><table><thead><tr><th>Ресурс</th><th>Действие</th><th>Изменение</th></tr></thead><tbody><tr v-for="c in p.changes" :key="`${c.resourceId}-${c.action}`"><td>{{ c.name }}</td><td>{{ labels[c.action] }}</td><td>{{ c.granted?'Выдать':'Отозвать' }}</td></tr></tbody></table></div><p>Персональные запреты: {{ p.denialsBefore.length }} → {{ p.denialsAfter.length }}. {{ denialMode==='keep'?'Сохраняются.':'Заменяются выбранным набором.' }}</p></details><button class="rp-primary" :disabled="!plan.count" @click="apply">Применить изменения</button></section>
     </template>
     <p v-else class="rp-empty">Выберите получателя прав.</p>
    </div>
   </div>
  </fieldset><p v-if="busy" role="status">Выполняется операция…</p>
 </main>
</template>
<style scoped src="./role-policy-preview.css"></style>
<style scoped>
.live-controls{border:0;padding:0;margin:0;min-width:0}.live-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:14px}.live-main{min-width:0}.live-subjects{align-self:start;position:sticky;top:0;max-height:75vh;overflow:auto}.live-subjects>label{display:flex;align-items:center;gap:9px;padding:8px;border-radius:6px}.live-subjects>label:first-child{display:grid;padding:0;margin-bottom:10px}.live-subjects small{display:block;color:var(--rp-muted);font-size:11px}.live-subjects strong{font-weight:500}.live-access .rp-roles>button{display:flex;flex-direction:column;align-items:flex-start;gap:7px}.live-access h2{margin-bottom:8px}.live-access summary{cursor:pointer;color:var(--rp-accent);padding:5px 0}.live-access details>label{display:block;margin:8px 0}.live-access .rp-plan button{margin-top:10px}.live-access .rp-table-scroll{max-height:360px}.live-access .rp-capabilities{margin:12px 0}@media(max-width:1000px){.live-layout{grid-template-columns:1fr}.live-subjects{position:static;max-height:260px}}
</style>
